import{_ as t,o,c as n,a0 as a}from"./chunks/framework.D4fUSYzX.js";const s="/my-little-software-factory/assets/decision-modal.BfFTa-9Q.png",g=JSON.parse('{"title":"Modals","description":"The decision modal and the missing modal, and the leftover environment fact.","frontmatter":{"title":"Modals","description":"The decision modal and the missing modal, and the leftover environment fact."},"headers":[],"relativePath":"operation/modals.md","filePath":"operation/modals.md"}'),r={name:"operation/modals.md"};function i(d,e,h,c,l,m){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="modals" tabindex="-1">Modals <a class="header-anchor" href="#modals" aria-label="Permalink to &quot;Modals&quot;">​</a></h1><h2 id="decision-modal" tabindex="-1">Decision modal <a class="header-anchor" href="#decision-modal" aria-label="Permalink to &quot;Decision modal&quot;">​</a></h2><p><img src="'+s+`" alt="The decision modal on an awaiting ticket: the turn log of the settled
turn above the choice rows"></p><p>Enter on an <code>awaiting</code> ticket opens the decision modal: a near-fullscreen modal that pops in over the app with a short fade and grow, one cell of margin on every side. In auto mode, and on an auto-close task type, the factory decides the ticket itself: Enter only reports that, and the modal stays closed. Its border reads <code>Decision: &lt;ticket title&gt;</code>, and the first row under the border names the context: repository, task type, agent, completion time.</p><p>The body is the turn log of the settled turn, in order. The agent&#39;s text blocks carry light markdown dressing: headings render bright without their hashes, bold renders bright, code renders dim, lists keep their markers and indent per level, links keep their label. Each tool call is one dim note, <code>▸ name: target</code>; a failed call wears the warning color. The agent&#39;s thinking text is not shown. The log comes from the agent&#39;s session record (ADR 0008); when no session is known, the terminal capture stands in. The modal opens at the bottom, where the agent&#39;s conclusion is, and a proportional scrollbar shows the position when the log is longer than the window.</p><p>The modal offers the choices the state allows. <code>Up</code> and <code>Down</code> move between the choice rows; <code>j</code> and <code>k</code> scroll the turn log one row, with the page and jump keys as aliases. <code>Enter</code> chooses the selected row, <code>e</code> edits the selected Handoff row&#39;s settings before it starts, and <code>Esc</code> closes the modal: nothing runs, and the ticket stays awaiting. The shared Action bar at the terminal bottom names these controls. The first row, &quot;Close&quot;, ends the work cycle: the ticket returns to open with its cycle number incremented, and the handoff&#39;s environment is closed without touching the git branch, so pushed work and pull requests survive: a worktree handoff loses its worktree checkout and its herdr workspace, a live worktree handoff loses its tab. The second row, &quot;Goto&quot;, focuses the agent&#39;s pane so the operator can steer it; the ticket stays where it is, <code>awaiting</code> until the poll moves it or the operator decides. The confirmation on the Message line names the workspace the pane lives in, since herdr 0.9 keeps each client&#39;s own view and a CLI focus no longer moves the operator&#39;s view (the Live view page carries the full note). Goto is navigation, not a completion decision, so the trace does not record it: the turn&#39;s pending trace stays pending, and the next settle refreshes it with the agent&#39;s new last message. Then one &quot;Handoff: <code>&lt;task type&gt;</code>&quot; row per outgoing workflow edge the completed task type has, in config order: an edge naming several targets offers one row per target, and two edges to the same target keep both rows, so every edge stays reachable. The row&#39;s detail shows the Agent the arriving handoff resolves to (the edge&#39;s pin, else the target Task profile&#39;s agent, else <code>default-agent</code>), and the edge&#39;s pinned environment when the edge defines one. Choosing a row hands the ticket off again with that target task type. <code>e</code> on such a row opens the override panel on the choice the edge resolved, so the operator can change the agent, environment, Model, or Thinking for this one handoff before it starts; the override outranks the edge pin, the Task profile, and the defaults. Moving that panel to another Task type re-derives the rows the operator never touched from the type&#39;s own profile, so the route&#39;s Agent pin goes with the target the edge named. <code>Esc</code> there closes the panel back to the decision: nothing is claimed and nothing runs. Enter on an awaiting ticket keeps the direct route, so a route the operator wants unchanged stays one press. The row&#39;s &quot;handed-off&quot; decision lands on the turn&#39;s trace only when the routed handoff settles with the agent started; a failed route leaves the trace pending, so Close and Goto keep working on the awaiting ticket. The automatic route decides the same way: its <code>auto-handed-off</code> record waits for the same start.</p><h2 id="missing-modal" tabindex="-1">Missing modal <a class="header-anchor" href="#missing-modal" aria-label="Permalink to &quot;Missing modal&quot;">​</a></h2><p>Enter on a ticket whose agent is missing opens the missing modal. It shows the badge fact and the handoff count, and it offers &quot;Restart&quot; and &quot;Abandon&quot;. <code>Up</code> and <code>Down</code> move between the choice rows, <code>j</code> and <code>k</code> scroll its message, <code>Enter</code> chooses the selected row, and <code>Esc</code> closes the modal: nothing runs, and the badge stays. The shared Action bar at the terminal bottom names these controls. &quot;Restart&quot; hands the ticket off again with the same choices, in the workspace the handoff recorded, and the last completion&#39;s message as the previous message. &quot;Abandon&quot; ends the work cycle: the ticket returns to open with its cycle number incremented, the handoff&#39;s environment is closed, and the missing badge clears.</p><h2 id="leftover-environment" tabindex="-1">Leftover environment <a class="header-anchor" href="#leftover-environment" aria-label="Permalink to &quot;Leftover environment&quot;">​</a></h2><p>The control plane offers no clear for a leftover environment (ADR 0032): key <code>w</code> on a ticket wearing the <code>leftover</code> marker changes nothing and opens no panel. The leftover stays a durable, visible fact - the <code>leftover</code> marker in the row, and the detail block that names the workspace, tab, and pane that remain, the reason the control plane knows, and since when. The block states that the cleanup runs in herdr, not in the control plane, the way the Consultation detail does for its remaining resources, so the operator knows where the environment still lives and goes there to remove it.</p><p>Every close still runs the Close cleanup: a removal that herdr refuses records the leftover with its reason, and the close stands. A handoff beside its ticket&#39;s leftover still starts under the cycle name (ADR 0012): the leftover&#39;s agent holding the stable name is the case the fact makes visible, not a failure of the start.</p>`,11)])])}const f=t(r,[["render",i]]);export{g as __pageData,f as default};
